// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 value, bytes calldata data) public {
        vm.assume(value <= address(c).balance);
        Reverter reverter = new Reverter();
        bool ok;
        try c.sendMoney(address(reverter), value, data) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
